const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/teardownexit";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
function write(file, text) {
  const p = path.join(dir, file);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, text);
}
function vitest(args, cwd) {
  const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", ...args], {
    cwd: cwd || dir,
    encoding: "utf8",
    env: { ...process.env, NO_COLOR: "1", CI: "1" },
    timeout: 60000,
  });
  return { status: r.status, out: (r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : "") };
}

write("globalSetup.mjs", [
  "export default function () {",
  "  return () => {",
  "    throw new Error('teardown error')",
  "  }",
  "}",
].join("\n") + "\n");
write("vitest.config.mjs", [
  "export default {",
  "  test: {",
  "    globalSetup: ['./globalSetup.mjs'],",
  "  },",
  "}",
].join("\n") + "\n");
write("example.test.mjs", [
  "import { expect, test } from 'vitest'",
  "test('example test', () => {",
  "  expect(1 + 1).toBe(2)",
  "})",
].join("\n") + "\n");
const r = vitest(["run", "--reporter=json", "--outputFile=report.json"]);
console.log(r.out);
const reportFile = path.join(dir, "report.json");
if (!fs.existsSync(reportFile)) {
  console.error("ERROR: vitest wrote no JSON report (exit " + r.status + ")");
  process.exit(2);
}
const report = JSON.parse(fs.readFileSync(reportFile, "utf8"));
const counts = "total " + report.numTotalTests + ", passed " + report.numPassedTests + ", failed " + report.numFailedTests;
console.log(counts);
if (report.numTotalTests !== 1 || report.numPassedTests !== 1) {
  console.error("ERROR: the test did not pass (" + counts + ", exit " + r.status + ")");
  process.exit(2);
}
if (!r.out.includes("teardown error")) {
  console.error("ERROR: the globalSetup teardown error was not reported (exit " + r.status + ")");
  process.exit(2);
}
if (r.status === 1) {
  console.log("PASS: vitest run exited 1 when the globalSetup teardown threw");
  process.exit(0);
}
if (r.status === 0) {
  console.error("FAIL: vitest run exited 0 although the globalSetup teardown threw");
  process.exit(1);
}
console.error("ERROR: unexpected exit code " + r.status);
process.exit(2);

